// analyzer/typeComplexity.ts:18
/// TS defaults: recursionCount = 0.
pub fn get_complexity_score_for_type(type_: P<Type>, recursion_count: u32) -> f64 {
    if recursion_count > MAX_TYPE_RECURSION_COUNT {
        return 1.0;
    }
    let recursion_count = recursion_count + 1;

    match type_.category {
        TypeCategory::Unknown | TypeCategory::Any => 0.5,

        TypeCategory::TypeVar => {
            // Assume type[T] is more complex than T.
            if TypeBase::is_instantiable(type_) {
                0.55
            } else {
                0.5
            }
        }

        TypeCategory::Function | TypeCategory::Overloaded => {
            // Classes and unions should be preferred over functions,
            // so make this relatively high (more than 0.75).
            if TypeBase::is_instantiable(type_) {
                0.85
            } else {
                0.8
            }
        }

        TypeCategory::Unbound | TypeCategory::Never => 1.0,

        TypeCategory::Union => {
            let mut max_score: f64 = 0.0;

            // If this union has a very large number of subtypes, don't bother
            // accurately computing the score. Assume a fixed value.
            let subtypes = UnionType(type_).d().priv_.borrow().subtypes.clone();
            if subtypes.len() < 16 {
                for subtype in subtypes {
                    let subtype_score = get_complexity_score_for_type(subtype, recursion_count);
                    max_score = max_score.max(subtype_score);
                }
            } else {
                max_score = 0.5;
            }

            max_score
        }

        TypeCategory::Class => get_complexity_score_for_class(ClassType(type_), recursion_count),

        // For all other types, return a score of 0.
        TypeCategory::Module => 0.0,
    }
}

// analyzer/typeComplexity.ts:72
pub(crate) fn get_complexity_score_for_class(class_type: ClassType, recursion_count: u32) -> f64 {
    let mut type_arg_score_sum: f64 = 0.0;
    let mut type_arg_count: u32 = 0;

    let (tuple_type_args, type_args) = {
        let priv_ = class_type.d().priv_.borrow();
        (priv_.tuple_type_args.map(|tuple_type_args| tuple_type_args.borrow().clone()), priv_.type_args.clone())
    };
    if let Some(tuple_type_args) = tuple_type_args {
        for type_arg in tuple_type_args {
            type_arg_score_sum += get_complexity_score_for_type(type_arg.type_, recursion_count);
            type_arg_count += 1;
        }
    } else if let Some(type_args) = type_args {
        for type_ in type_args {
            type_arg_score_sum += get_complexity_score_for_type(type_, recursion_count);
            type_arg_count += 1;
        }
    } else {
        // `shared.typeParams` is always an array, so this branch always runs.
        let type_param_count = class_type.d().shared.get().type_params.borrow().len();
        for _ in 0..type_param_count {
            type_arg_score_sum +=
                get_complexity_score_for_type(AnyType::create(false).0, recursion_count);
            type_arg_count += 1;
        }
    }

    let average_type_arg_complexity = if type_arg_count > 0 {
        type_arg_score_sum / f64::from(type_arg_count)
    } else {
        0.0
    };
    let mut result = 0.5 + average_type_arg_complexity * 0.25;

    // Assume type[T] is more complex than T.
    if is_instantiable_class(class_type.0) {
        result += 0.05;
    }

    result
}
